def month_series(n):
    """最近 n 个月的 YYYY-MM 列表（含当月，升序）。"""
    now = datetime.now()
    y, m = now.year, now.month
    out = []
    for _ in range(n):
        out.append(f"{y:04d}-{m:02d}")
        m -= 1
        if m == 0:
            m, y = 12, y - 1
    return list(reversed(out))


