  }
  const pct = Math.min(100, b.percent);
  let statusText, cls;
  if(b.status === "over"){
    cls = "over";
    statusText = "⚠️ 已超预算 ¥" + fmt(b.used - b.monthly_budget);
  }else if(b.status === "warn"){
    cls = "warn";
    statusText = "⚠️ 已用预算 " + b.percent + "%, 接近上限";
  }else{
    cls = "ok";
    statusText = "已用 " + b.percent + "% · 剩余 ¥" + fmt(b.monthly_budget - b.used);
  }
  box.innerHTML =
    '<div class="budget-head"><span>月支出预算</span><span class="budget-form"><input id="budget-input" type="number" min="0" step="100" value="' + b.monthly_budget + '">' + save + '</span></div>' +
