    '<div class="budget-status ' + cls + '">' + statusText + '</div>';
}

function renderTrend(t){
  const el = $("#trend");
  if(!t || !t.months.length || !t.income.concat(t.expense).some(v => v > 0)){
    el.innerHTML = '<div class="empty">近 6 个月暂无收支数据</div>';
    return;
  }
  const max = Math.max(1, ...t.income.concat(t.expense));
  el.innerHTML = t.months.map((m, i) => {
    const inc = t.income[i], exp = t.expense[i];
    const ih = Math.max(2, inc / max * 100), eh = Math.max(2, exp / max * 100);
    const label = Number(m.split("-")[1]) + "月";
    return '<div class="trend-col">' +
      '<div class="trend-bars">' +
        '<div class="tbar income" style="height:' + ih + '%" title="' + label + ' 收入 ' + money(inc) + '">' + (inc > 0 ? '<span class="tbar-val">' + fmt(inc) + "</span>" : "") + "</div>" +
        '<div class="tbar expense" style="height:' + eh + '%" title="' + label + ' 支出 ' + money(exp) + '">' + (exp > 0 ? '<span class="tbar-val">' + fmt(exp) + "</span>" : "") + "</div>" +
      "</div>" +
      '<div class="trend-month">' + label + "</div>" +
    "</div>";
  }).join("");
}

