def set_settings(payload):
    data = load()
    settings = data.setdefault("settings", {})
    if "monthly_budget" in payload:
        try:
            v = float(payload["monthly_budget"])
        except (TypeError, ValueError):
            return None, "monthly_budget 必须是数字"
        if v < 0 or v > 1e12:
            return None, "monthly_budget 必须 >= 0"
        settings["monthly_budget"] = round(v, 2)
    if "category_budgets" in payload:
        cb = payload["category_budgets"]
        if not isinstance(cb, dict):
            return None, "category_budgets 必须是 {分类: 金额} 对象"
        cleaned = {}
        for k, val in cb.items():
            name = str(k).strip()
            if not name or val in (None, ""):
                continue
            try:
                v = float(val)
            except (TypeError, ValueError):
                return None, f"分类 [{name}] 的预算必须是数字"
            if v < 0 or v > 1e12:
                return None, f"分类 [{name}] 的预算必须 >= 0"
            if v > 0:
                cleaned[name] = round(v, 2)
        settings["category_budgets"] = cleaned
    save(data)
    return settings, None
