"""


def _esc_html(s):
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


def valid_month(m):
    try:
        datetime.strptime(str(m) + "-01", "%Y-%m-%d")
        return True
    except ValueError:
        return False


def report_html(month):
    """生成月度报表 HTML（浏览器可打印/另存为 PDF）。"""
    s = summarize(month)
    recs = records_of(month)
    y, mo = month.split("-")
    title = f"{y}年{int(mo)}月"
    now = datetime.now().strftime("%Y-%m-%d %H:%M")

    def cat_rows(items, total):
        if not items:
            return '<tr><td colspan="5" style="text-align:center;color:#94a3b8">暂无记录</td></tr>'
        rows = []
        for it in items:
            share = f"{it['total'] / total * 100:.1f}%" if total > 0 else "-"
            budget = ""
            if it.get("budget"):
                if it["status"] == "over":
                    budget = "⚠️ 超支 ¥%.2f" % (it["total"] - it["budget"])
                elif it["status"] == "warn":
                    budget = "▲ 已用 %s%%" % it["percent"]
                else:
                    budget = "✓ 预算内 %s%%" % it["percent"]
            rows.append(
                f"<tr><td>{_esc_html(it['category'])}</td>"
                f"<td style='text-align:center'>{it['count']}</td>"
                f"<td>¥{it['total']:.2f}</td><td>{share}</td><td>{budget}</td></tr>")
        return "\n".join(rows)

    def rec_rows():
        if not recs:
            return '<tr><td colspan="5" style="text-align:center;color:#94a3b8">暂无记录</td></tr>'
        rows = []
        for r in recs:
            sign = "-" if r["type"] == "expense" else "+"
            t = "支出" if r["type"] == "expense" else "收入"
            rows.append(
                f"<tr><td>{_esc_html(r.get('date', ''))}</td>"
                f"<td style='text-align:center'>{t}</td>"
                f"<td>{_esc_html(r.get('category', ''))}</td>"
                f"<td>{_esc_html(r.get('note', ''))}</td>"
                f"<td>{sign}¥{float(r.get('amount', 0)):.2f}</td></tr>")
        return "\n".join(rows)

    b = s["budget"]
    if b["status"] == "none":
        budget_html = ""
    else:
        if b["status"] == "over":
            mark = "⚠️ 已超支 ¥%.2f" % (b["used"] - b["monthly_budget"])
        elif b["status"] == "warn":
            mark = "▲ 接近上限"
        else:
            mark = "✓ 预算内"
        budget_html = (
            "<h2>月支出预算 " + mark + "</h2>"
            "<table><tr><th>预算</th><th>已用</th><th>使用率</th><th>状态</th></tr>"
            f"<tr><td>¥{b['monthly_budget']:.2f}</td><td>¥{b['used']:.2f}</td>"
            f"<td>{b['percent']}%</td><td>{mark}</td></tr></table>")

    return (
        "<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'>"
        f"<title>月度收支报表 · {title}</title><style>{REPORT_CSS}</style></head><body>"
        "<div class='page'>"
        "<h1>📊 月度收支报表</h1>"
        f"<div class='sub'>vc-ledger · {title} · 共 {s['count']} 笔 · 生成于 {now}</div>"
        "<div class='totals'>"
        f"<div class='t'><div class='l'>收入</div><div class='v inc'>¥{s['income_total']:.2f}</div></div>"
        f"<div class='t'><div class='l'>支出</div><div class='v exp'>¥{s['expense_total']:.2f}</div></div>"
        f"<div class='t'><div class='l'>结余</div><div class='v'>¥{s['balance']:.2f}</div></div>"
        f"<div class='t'><div class='l'>笔数</div><div class='v'>{s['count']}</div></div></div>"
        + budget_html
        + "<h2>支出分类汇总</h2>"
        + "<table><tr><th>分类</th><th style='text-align:center'>笔数</th><th>金额</th><th>占比</th><th>预算</th></tr>"
        + cat_rows(s["expense_categories"], s["expense_total"]) + "</table>"
        + "<h2>收入分类汇总</h2>"
        + "<table><tr><th>分类</th><th style='text-align:center'>笔数</th><th>金额</th><th>占比</th><th>预算</th></tr>"
        + cat_rows(s["income_categories"], s["income_total"]) + "</table>"
        + "<h2>明细</h2>"
        + "<table><tr><th>日期</th><th>类型</th><th>分类</th><th>备注</th><th>金额</th></tr>"
        + rec_rows() + "</table>"
        + "<div class='footer'>本报表由 vc-ledger 生成 · 数据源 data/ledger.json · 浏览器打印 (Cmd/Ctrl+P) 可另存为 PDF</div>"
        + "</div></body></html>")


class Handler(BaseHTTPRequestHandler):
