def ensure_migrated(data):
    """兼容 v1 数据：无 books 结构时创建默认账本，无 book_id 的记录归入默认账本。"""
    data.setdefault("records", [])
    if not data.get("books"):
        old_settings = data.get("settings", {}) or {}
        data["books"] = [{
            "id": uuid.uuid4().hex[:12],
            "name": "默认账本",
            "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "settings": {"monthly_budget": float(old_settings.get("monthly_budget", 0) or 0),
                         "category_budgets": old_settings.get("category_budgets", {}) or {}},
        }]
        data.pop("settings", None)
    default_id = data["books"][0]["id"]
    changed = False
    for r in data["records"]:
        if not r.get("book_id"):
            r["book_id"] = default_id
            changed = True
    return data, changed


def first_book_id():
    return load()["books"][0]["id"]


def book_settings(book_id=None):
    bid = book_id or first_book_id()
    for b in load()["books"]:
        if b["id"] == bid:
            return b.get("settings", {}) or {}
    return {}


def book_name(book_id=None):
    bid = book_id or first_book_id()
    for b in load()["books"]:
        if b["id"] == bid:
            return b["name"]
    return "默认账本"


def list_books():
    data = load()
    return [{"id": b["id"], "name": b["name"], "created_at": b.get("created_at", ""),
             "count": sum(1 for r in data["records"] if r.get("book_id") == b["id"])}
            for b in data["books"]]


def create_book(name):
    name = str(name).strip()
    if not name:
        return None, "账本名称不能为空"
    if len(name) > 30:
        return None, "账本名称过长 (≤30字)"
    data = load()
    book = {"id": uuid.uuid4().hex[:12], "name": name,
            "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "settings": {"monthly_budget": 0.0, "category_budgets": {}}}
    data["books"].append(book)
    save(data)
    return book, None


def rename_book(bid, name):
    name = str(name).strip()
    if not name:
        return None, "账本名称不能为空"
    data = load()
    for b in data["books"]:
        if b["id"] == bid:
            b["name"] = name
            save(data)
            return b, None
    return None, "账本不存在"


def delete_book(bid):
    data = load()
    if len(data["books"]) <= 1:
        return "至少保留一个账本"
