$("#book-select").addEventListener("change", () => {
  bookId = $("#book-select").value;
  try{ localStorage.setItem("vc-ledger-book", bookId); }catch(e){}
  resetEditForm();
  refresh();
});
$("#book-new").addEventListener("click", async () => {
  const name = prompt("新账本名称:");
  if(name == null || !name.trim()) return;
  try{
    const b = await api("/api/books", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({name: name.trim()})});
    bookId = b.id;
    try{ localStorage.setItem("vc-ledger-book", bookId); }catch(e){}
    await loadBooks();
    refresh();
  }catch(err){ alert(err.message); }
});
$("#book-rename").addEventListener("click", async () => {
  const cur = booksCache.find(b => b.id === bookId);
  if(!cur) return;
  const name = prompt("重命名账本:", cur.name);
  if(name == null || !name.trim()) return;
  try{
    await api("/api/books/" + encodeURIComponent(bookId), {method: "PUT", headers: {"Content-Type": "application/json"}, body: JSON.stringify({name: name.trim()})});
    await loadBooks();
    refresh();
  }catch(err){ alert(err.message); }
});
$("#book-del").addEventListener("click", async () => {
  if(booksCache.length <= 1){ alert("至少保留一个账本"); return; }
  const cur = booksCache.find(b => b.id === bookId);
  if(!confirm("删除账本「" + (cur ? cur.name : "") + "」? (仅可删除空账本)")) return;
  try{
    await api("/api/books/" + encodeURIComponent(bookId), {method: "DELETE"});
    bookId = null;
    try{ localStorage.removeItem("vc-ledger-book"); }catch(e){}
    await loadBooks();
    refresh();
  }catch(err){ alert(err.message); }
});

